// --- Global State ---
let typingTimeout;
let stageInterval;
let currentStreamingMessage = null;
let streamingMessageElement = null;

// --- Profile Image Cookie Cache ---
const PROFILE_IMAGE_COOKIE = 'apilage_profile_image';
const PROFILE_IMAGE_TS_COOKIE = 'apilage_profile_image_ts';
const PROFILE_IMAGE_TTL_MS = 1000 * 60 * 60 * 24 * 7;
const PROFILE_IMAGE_COOKIE_PATH = '/app';

function setCookie(name, value, maxAgeSeconds) {
    if (!name) return;
    const secure = window.location.protocol === 'https:' ? '; Secure' : '';
    const maxAge = Number.isFinite(maxAgeSeconds) ? `; Max-Age=${Math.max(0, Math.floor(maxAgeSeconds))}` : '';
    document.cookie = `${encodeURIComponent(name)}=${encodeURIComponent(value || '')}${maxAge}; Path=${PROFILE_IMAGE_COOKIE_PATH}; SameSite=Lax${secure}`;
}

function getCookie(name) {
    if (!name) return '';
    const prefix = `${encodeURIComponent(name)}=`;
    const parts = document.cookie ? document.cookie.split(';') : [];
    for (const part of parts) {
        const trimmed = part.trim();
        if (trimmed.startsWith(prefix)) {
            return decodeURIComponent(trimmed.slice(prefix.length));
        }
    }
    return '';
}

function clearCookie(name) {
    setCookie(name, '', 0);
}

function isPlaceholderImage(url) {
    const v = String(url || '');
    if (!v) return true;
    const lower = v.toLowerCase();
    return lower.includes('/assets/images/user.png') || lower.endsWith('/user.png');
}

function setProfileImageCache(url) {
    const val = String(url || '').trim();
    if (!val || isPlaceholderImage(val)) return;
    const maxAge = Math.floor(PROFILE_IMAGE_TTL_MS / 1000);
    setCookie(PROFILE_IMAGE_COOKIE, val, maxAge);
    setCookie(PROFILE_IMAGE_TS_COOKIE, String(Date.now()), maxAge);
}

function getProfileImageCache() {
    const url = getCookie(PROFILE_IMAGE_COOKIE);
    const ts = Number(getCookie(PROFILE_IMAGE_TS_COOKIE));
    if (!url || !Number.isFinite(ts)) return '';
    if (Date.now() - ts > PROFILE_IMAGE_TTL_MS) {
        clearCookie(PROFILE_IMAGE_COOKIE);
        clearCookie(PROFILE_IMAGE_TS_COOKIE);
        return '';
    }
    return url;
}

function applyCachedProfileImage() {
    const cached = getProfileImageCache();
    if (!cached) return;
    const targets = document.querySelectorAll('#profilePhoto, .sidebar-footer-userinfo .user-avatar img');
    targets.forEach((img) => {
        if (!img || !cached) return;
        if (img.getAttribute('src') !== cached) {
            img.setAttribute('src', cached);
        }
        img.decoding = 'async';
        if (img.id === 'profilePhoto') {
            img.loading = 'lazy';
        }
    });
}

function primeProfileImageCacheFromDom() {
    if (getProfileImageCache()) return;
    const img = document.querySelector('.sidebar-footer-userinfo .user-avatar img');
    const src = img ? img.getAttribute('src') || '' : '';
    if (src) setProfileImageCache(src);
}

window.setProfileImageCache = setProfileImageCache;
window.getProfileImageCache = getProfileImageCache;
window.applyCachedProfileImage = applyCachedProfileImage;

if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', () => {
        primeProfileImageCacheFromDom();
        applyCachedProfileImage();
    });
} else {
    primeProfileImageCacheFromDom();
    applyCachedProfileImage();
}

// --- Collaboration Voice State ---
// ===== Collaborative voice (minimal Discord-like mic toggle) =====
const collabVoice = {
    enabled: false,
    conversationId: null,
    mode: 'off', // 'off' | 'listen' | 'talk'
    localStream: null,
    audioContext: null,
    analyser: null,
    analyserData: null,
    analyserRAF: null,
    lastSpeakingEmit: 0,
    isSpeaking: false,
    peers: new Map(), // socketId -> { pc, audioEl, remoteUserId, polite, makingOffer, ignoreOffer, pendingCandidates }
    speakingUsers: new Set(),
};


// --- Mentions: State + UI ---
// ===== Collaborator @mentions =====
const mentionState = {
    active: false,
    startIndex: -1,
    query: '',
    items: [], // { userId, name, image, isBot?: boolean }
    selectedIndex: 0,
};

function isMentionDropdownOpen(dropdownEl) {
    return !!dropdownEl && dropdownEl.style.display === 'block' && mentionState.active;
}

function normalizeNameForMatch(s) {
    return String(s || '').trim().toLowerCase();
}

function getCollaboratorsForMention() {
    const myUserId = Number(window.userData?.id || 0);
    const map = window.conversationParticipantsById || {};
    return Object.keys(map)
        .map((id) => {
            const userId = Number(id);
            const info = map[id] || {};
            return {
                userId,
                name: info.name || `User ${id}`,
                image: info.image || '',
            };
        })
        .filter((u) => u.userId && u.userId !== myUserId);
}

function getApilageAiMentionCandidate() {
    return {
        userId: 0,
        name: 'apilageai',
        image: '',
        isBot: true,
    };
}

function getCanvasMentionCandidate() {
    return {
        userId: -1,
        name: 'canvas',
        image: '',
        isCanvas: true,
        aliases: ['canves'],
    };
}

function getMentionCandidates() {
    // Always include the assistant in collaborative chats.
    return [getApilageAiMentionCandidate(), getCanvasMentionCandidate(), ...getCollaboratorsForMention()];
}

function renderMentionDropdown(dropdownEl) {
    if (!dropdownEl) return;
    dropdownEl.innerHTML = '';

    if (!mentionState.items.length) {
        const div = document.createElement('div');
        div.textContent = 'No matches';
        div.classList.add('ghost-style');
        dropdownEl.appendChild(div);
        return;
    }

    mentionState.items.forEach((item, idx) => {
        const div = document.createElement('div');
        div.className = 'mention-suggestion' + (idx === mentionState.selectedIndex ? ' is-active' : '');
        if (item.isCanvas) div.classList.add('mention-canvas');

        const imgUrl = item.image ? toFullImageUrl(item.image) : APP_USER_PLACEHOLDER;

        div.innerHTML = `
            <img class="mention-avatar" src="${imgUrl}" alt="" loading="lazy" decoding="async" onerror="this.onerror=null;this.src='${APP_USER_PLACEHOLDER}';" />
            <span class="mention-name">${item.name}</span>
        `;
        div.addEventListener('mousedown', (e) => {
            // Prevent textarea blur
            e.preventDefault();
        });
        div.addEventListener('click', () => {
            mentionState.selectedIndex = idx;
            applySelectedMention();
        });
        dropdownEl.appendChild(div);
    });
}

function findMentionAtCursor(inputEl) {
    const cursorPos = inputEl.selectionStart;
    const value = inputEl.value;
    const before = value.slice(0, cursorPos);
    const atIndex = before.lastIndexOf('@');
    if (atIndex === -1) return null;
    // Only trigger if @ starts a token (start or whitespace)
    const prevChar = atIndex > 0 ? before[atIndex - 1] : ' ';
    if (prevChar && !/\s/.test(prevChar)) return null;

    const afterAt = before.slice(atIndex + 1);
    // If contains whitespace/newline, not a mention token
    if (/\s/.test(afterAt)) return null;
    return { atIndex, query: afterAt };
}

function updateMentionState(inputEl, dropdownEl) {
    const info = findMentionAtCursor(inputEl);
    if (!info) {
        mentionState.active = false;
        return;
    }

    const query = normalizeNameForMatch(info.query);
    const candidates = getMentionCandidates();
    const matchesCandidate = (candidate, q) => {
        if (!q) return true;
        const name = normalizeNameForMatch(candidate?.name || '');
        if (name && name.includes(q)) return true;
        const aliases = Array.isArray(candidate?.aliases) ? candidate.aliases : [];
        return aliases.some((alias) => normalizeNameForMatch(alias).includes(q));
    };
    const items = candidates
        .filter((c) => matchesCandidate(c, query))
        .slice(0, 8);

    mentionState.active = true;
    mentionState.startIndex = info.atIndex;
    mentionState.query = info.query;
    mentionState.items = items;
    mentionState.selectedIndex = Math.max(0, Math.min(mentionState.selectedIndex, items.length - 1));
    renderMentionDropdown(dropdownEl);
}

function applySelectedMention() {
    const inputEl = document.getElementById('message-input');
    const dropdownEl = document.getElementById('suggestions-dropdown');
    if (!inputEl || !dropdownEl) return;
    if (!mentionState.active || !mentionState.items.length) return;

    const item = mentionState.items[mentionState.selectedIndex];
    if (!item) return;

    const cursorPos = inputEl.selectionStart;
    const value = inputEl.value;
    const before = value.substring(0, mentionState.startIndex);
    const after = value.substring(cursorPos);
    const inserted = `@${item.name} `;

    inputEl.value = before + inserted + after;
    const newPos = (before + inserted).length;
    inputEl.focus();
    inputEl.setSelectionRange(newPos, newPos);

    mentionState.active = false;
    dropdownEl.style.display = 'none';
}


// --- Mentions: Text Scanning Helpers ---
function extractMentionedUserIdsFromText(text) {
    if (!window.isCollaborativeChat) return [];
    const normalizedText = String(text || '').toLowerCase();
    const collaborators = getCollaboratorsForMention();
    const mentioned = [];
    for (const c of collaborators) {
        const token = `@${String(c.name || '').toLowerCase()}`;
        if (!token || token.length < 2) continue;
        if (normalizedText.includes(token)) {
            mentioned.push(c.userId);
        }
    }
    return Array.from(new Set(mentioned));
}

function hasApilageAiMention(text) {
    const t = String(text || '');
    return /(^|\s)@apilageai(?=[\s\.,!?]|$)/i.test(t);
}

function stripApilageAiMention(text) {
    const t = String(text || '');
    const stripped = t.replace(/(^|\s)@apilageai(?=[\s\.,!?]|$)/gi, '$1');
    return stripped.replace(/\s{2,}/g, ' ').trim();
}

function hasCanvasMention(text) {
    const t = String(text || '');
    return /(^|\s)@canv(?:as|es)(?=[\s\.,!?]|$)/i.test(t);
}


// --- Text / HTML Helpers ---
function escapeRegExp(str) {
    return String(str || '').replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

function escapeHtml(str) {
    return String(str ?? '')
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&#39;');
}

function getUploadsBase() {
    const raw = (window.UPLOADS_BASE_URL || '').trim();
    const base = raw || 'https://socket.apilageai.lk';
    return base.replace(/\/$/, '');
}

function highlightCollaboratorMentionsInText(text) {
    let out = String(text || '');
    const candidates = getMentionCandidates();
    for (const c of candidates) {
        const name = String(c?.name || '').trim();
        if (!name) continue;
        const pattern = c?.isCanvas
            ? /(^|\s)(@canv(?:as|es))(?=[\s\.,!?]|$)/gi
            : new RegExp(`(^|\\s)(@${escapeRegExp(name)})(?=[\\s\\.,!?]|$)`, 'gi');
        out = out.replace(pattern, (m, prefix, mention) => {
            const cls = c?.isCanvas ? 'chat-mention chat-mention-canvas' : 'chat-mention';
            return `${prefix}<span class="${cls}">${mention}</span>`;
        });
    }
    return out;
}


// --- Collaboration Voice: Peer Helpers ---
function getMyUserId() {
    return Number(window.userData?.id || 0);
}

function isPolitePeer(remoteUserId, remoteSocketId) {
    const myUserId = getMyUserId();
    const theirUserId = Number(remoteUserId || 0);
    if (myUserId && theirUserId) return myUserId > theirUserId;
    // Fallback (still deterministic): compare socket ids lexicographically
    return String(socket.id || '') > String(remoteSocketId || '');
}

function shouldInitiateOffer(remoteUserId, remoteSocketId) {
    const myUserId = getMyUserId();
    const theirUserId = Number(remoteUserId || 0);
    if (myUserId && theirUserId) return myUserId < theirUserId;
    // Fallback (still deterministic): smaller socket id initiates
    return String(socket.id || '') < String(remoteSocketId || '');
}

function setMicButtonVisible(visible) {
    const btn = document.getElementById('collab-mic-toggle');
    if (!btn) return;
    btn.style.display = visible ? '' : 'none';
}

function setMicButtonState(isUnmuted) {
    const btn = document.getElementById('collab-mic-toggle');
    if (!btn) return;
    const icon = btn.querySelector('i');
    btn.classList.toggle('is-unmuted', !!isUnmuted);
    if (icon) {
        icon.className = isUnmuted ? 'fa fa-microphone' : 'fa fa-microphone-slash';
    }
}

function updateSpeakingIndicator() {
    const el = document.getElementById('collab-speaking-indicator');
    if (!el) return;
    if (!collabVoice.speakingUsers.size) {
        el.style.display = 'none';
        el.textContent = '';
        return;
    }
    const names = Array.from(collabVoice.speakingUsers)
        .map((uid) => getCollaboratorNameById(uid))
        .filter(Boolean);
    if (!names.length) {
        el.style.display = 'none';
        el.textContent = '';
        return;
    }
    const label = names.length === 1 ? `${names[0]} is talking` : `${names.slice(0, 2).join(', ')}${names.length > 2 ? '…' : ''} are talking`;
    el.textContent = label;
    el.style.display = '';
}

function isCollaborativeChatActive() {
    const ids = Object.keys(window.conversationParticipantsById || {});
    return ids.length > 1;
}


// --- WebRTC: Configuration ---
function getRtcConfig() {
    return {
        iceServers: [
            { urls: 'stun:stun.l.google.com:19302' },
            { urls: 'stun:stun1.l.google.com:19302' },
            { urls: 'stun:stun2.l.google.com:19302' },
            { urls: 'stun:stun3.l.google.com:19302' },
            { urls: 'stun:stun4.l.google.com:19302' },
            // Additional public STUN (helps in some enterprise NAT scenarios)
            { urls: 'stun:global.stun.twilio.com:3478' },
        ],
        bundlePolicy: 'max-bundle',
        rtcpMuxPolicy: 'require',
        iceCandidatePoolSize: 4,
    };
}


// --- Collaboration Voice: Peer Lifecycle ---
function closePeer(socketId) {
    const peer = collabVoice.peers.get(socketId);
    if (!peer) return;
    if (peer.disconnectedTimer) {
        try {
            clearTimeout(peer.disconnectedTimer);
        } catch (_) { }
        peer.disconnectedTimer = null;
    }
    try {
        peer.pc?.close();
    } catch (_) { }
    try {
        peer.audioEl?.remove();
    } catch (_) { }
    collabVoice.peers.delete(socketId);
}


// --- Collaboration Voice: Speaking Indicator ---
function stopSpeakingAnalyser() {
    if (collabVoice.analyserRAF) {
        cancelAnimationFrame(collabVoice.analyserRAF);
        collabVoice.analyserRAF = null;
    }
    collabVoice.analyser = null;
    collabVoice.analyserData = null;
    try {
        collabVoice.audioContext?.close();
    } catch (_) { }
    collabVoice.audioContext = null;
}

function startSpeakingAnalyser() {
    stopSpeakingAnalyser();
    if (!collabVoice.localStream) return;
    try {
        const AudioContextCtor = window.AudioContext || window.webkitAudioContext;
        if (!AudioContextCtor) return;
        const ctx = new AudioContextCtor();
        const source = ctx.createMediaStreamSource(collabVoice.localStream);
        const analyser = ctx.createAnalyser();
        analyser.fftSize = 512;
        const data = new Uint8Array(analyser.frequencyBinCount);
        source.connect(analyser);
        collabVoice.audioContext = ctx;
        collabVoice.analyser = analyser;
        collabVoice.analyserData = data;

        const tick = () => {
            if (!collabVoice.enabled || !collabVoice.analyser) return;
            collabVoice.analyser.getByteFrequencyData(collabVoice.analyserData);
            let sum = 0;
            for (let i = 0; i < collabVoice.analyserData.length; i++) sum += collabVoice.analyserData[i];
            const avg = sum / collabVoice.analyserData.length;
            const now = Date.now();

            // Simple threshold with debounce
            const speakingNow = avg > 22;
            if (speakingNow !== collabVoice.isSpeaking && now - collabVoice.lastSpeakingEmit > 250) {
                collabVoice.isSpeaking = speakingNow;
                collabVoice.lastSpeakingEmit = now;
                socket.emit('voice_speaking', {
                    conversation_id: collabVoice.conversationId,
                    speaking: speakingNow,
                });
            }
            collabVoice.analyserRAF = requestAnimationFrame(tick);
        };
        collabVoice.analyserRAF = requestAnimationFrame(tick);
    } catch (e) {
        // ignore analyser failures
    }
}


// --- Collaboration Voice: Public API ---
async function enableCollabVoice(conversationId) {
    // Backwards-compatible: enable voice in TALK mode (explicit user click)
    const cid = Number(conversationId);
    if (!cid) return;
    await enableCollabVoiceTalk(cid);
}


// --- Collaboration Voice: Public API ---
async function enableCollabVoiceListen(conversationId) {
    const cid = Number(conversationId);
    if (!cid) return;
    if (collabVoice.enabled && collabVoice.conversationId === cid && collabVoice.mode === 'listen') return;

    // Reset if switching conversations or changing mode
    if (collabVoice.enabled) {
        await disableCollabVoice();
    }

    collabVoice.conversationId = cid;
    collabVoice.enabled = true;
    collabVoice.mode = 'listen';
    collabVoice.localStream = null;

    setMicButtonState(false);
    try {
        socket.emit('voice_join', { conversation_id: cid });
    } catch (_) { }
}


// --- Collaboration Voice: Public API ---
async function enableCollabVoiceTalk(conversationId) {
    const cid = Number(conversationId);
    if (!cid) return;
    if (collabVoice.enabled && collabVoice.conversationId === cid && collabVoice.mode === 'talk') return;

    // Reset (simpler + avoids renegotiation edge-cases)
    if (collabVoice.enabled) {
        await disableCollabVoice();
    }

    collabVoice.conversationId = cid;
    collabVoice.enabled = true;
    collabVoice.mode = 'talk';

    if (!collabVoice.localStream) {
        collabVoice.localStream = await navigator.mediaDevices.getUserMedia({ audio: true });
    }
    collabVoice.localStream.getAudioTracks().forEach((t) => (t.enabled = true));

    setMicButtonState(true);
    socket.emit('voice_join', { conversation_id: cid });
    startSpeakingAnalyser();
}

async function disableCollabVoice() {
    if (!collabVoice.enabled) {
        setMicButtonState(false);
        return;
    }

    try {
        socket.emit('voice_leave', { conversation_id: collabVoice.conversationId });
        socket.emit('voice_speaking', { conversation_id: collabVoice.conversationId, speaking: false });
    } catch (_) { }

    stopSpeakingAnalyser();

    collabVoice.localStream?.getTracks()?.forEach((t) => {
        try {
            t.stop();
        } catch (_) { }
    });
    collabVoice.localStream = null;

    for (const socketId of Array.from(collabVoice.peers.keys())) {
        closePeer(socketId);
    }
    collabVoice.peers.clear();

    collabVoice.enabled = false;
    collabVoice.mode = 'off';
    collabVoice.isSpeaking = false;
    collabVoice.speakingUsers.clear();
    updateSpeakingIndicator();
    setMicButtonState(false);
    collabVoice.conversationId = null;
}


// --- WebRTC: Peer Connection ---
async function ensurePeerConnection(remoteSocketId) {
    if (!collabVoice.enabled) return null;
    if (collabVoice.peers.has(remoteSocketId)) return collabVoice.peers.get(remoteSocketId);

    const pc = new RTCPeerConnection(getRtcConfig());
    // If we're in listen mode (or before mic granted), request audio receive.
    if (!collabVoice.localStream) {
        try {
            pc.addTransceiver('audio', { direction: 'recvonly' });
        } catch (_) { }
    } else {
        collabVoice.localStream.getTracks().forEach((track) => pc.addTrack(track, collabVoice.localStream));
    }

    const audioEl = document.createElement('audio');
    audioEl.autoplay = true;
    audioEl.playsInline = true;
    audioEl.className = 'hidden';
    document.body.appendChild(audioEl);

    pc.ontrack = (ev) => {
        const [stream] = ev.streams;
        if (stream) {
            audioEl.srcObject = stream;
            audioEl.muted = false;
            audioEl.volume = 1;
            // Autoplay may still be blocked, but try.
            try {
                const p = audioEl.play();
                if (p && typeof p.catch === 'function') p.catch(() => { });
            } catch (_) { }
        }
    };

    pc.onicecandidate = (ev) => {
        if (ev.candidate) {
            socket.emit('voice_ice', {
                conversation_id: collabVoice.conversationId,
                to_socket_id: remoteSocketId,
                candidate: ev.candidate,
            });
        }
    };

    const entry = {
        pc,
        audioEl,
        remoteUserId: null,
        polite: isPolitePeer(null, remoteSocketId),
        makingOffer: false,
        ignoreOffer: false,
        pendingCandidates: [],
        disconnectedTimer: null,
        lastIceRestartAt: 0,
    };

    const maybeRecover = async (reason) => {
        if (!collabVoice.enabled) return;
        const now = Date.now();
        if (now - (entry.lastIceRestartAt || 0) < 4000) return;
        entry.lastIceRestartAt = now;
        try {
            if (typeof pc.restartIce === 'function') pc.restartIce();
        } catch (_) { }
        try {
            // Only the designated initiator should renegotiate.
            if (shouldInitiateOffer(entry.remoteUserId, remoteSocketId)) {
                await createOfferTo(remoteSocketId);
            }
        } catch (_) { }
    };

    pc.oniceconnectionstatechange = () => {
        const st = pc.iceConnectionState;
        if (st === 'failed') {
            maybeRecover('ice-failed');
            return;
        }
        if (st === 'disconnected') {
            if (entry.disconnectedTimer) clearTimeout(entry.disconnectedTimer);
            entry.disconnectedTimer = setTimeout(() => {
                entry.disconnectedTimer = null;
                if (pc.iceConnectionState === 'disconnected') {
                    maybeRecover('ice-disconnected');
                }
            }, 2500);
            return;
        }
        if (st === 'connected' || st === 'completed') {
            if (entry.disconnectedTimer) {
                clearTimeout(entry.disconnectedTimer);
                entry.disconnectedTimer = null;
            }
        }
    };

    collabVoice.peers.set(remoteSocketId, entry);
    return entry;
}

async function createOfferTo(remoteSocketId) {
    const entry = await ensurePeerConnection(remoteSocketId);
    if (!entry) return;
    // Prevent overlapping negotiations
    if (entry.pc.signalingState !== 'stable') return;

    try {
        entry.makingOffer = true;
        const offer = await entry.pc.createOffer();
        await entry.pc.setLocalDescription(offer);
        socket.emit('voice_offer', {
            conversation_id: collabVoice.conversationId,
            to_socket_id: remoteSocketId,
            sdp: entry.pc.localDescription,
        });
    } catch (_) {
        // ignore
    } finally {
        entry.makingOffer = false;
    }
}


// --- Collaboration: Participants + Labels ---
// Collaboration display helpers
window.conversationParticipantsById = window.conversationParticipantsById || {};
let participantsFetchInFlight = null;

async function ensureConversationParticipants(conversationId) {
    const cid = Number(conversationId);
    if (!cid) return;
    if (participantsFetchInFlight) return participantsFetchInFlight;

    participantsFetchInFlight = (async () => {
        try {
            const resp = await fetch(`${EFFECTIVE_NODE_API_BASE}/api/conversations/${cid}/participants`, {
                credentials: 'include'
            });
            const data = await safeJson(resp);
            if (data && !data.error && Array.isArray(data.participants)) {
                const next = {};
                data.participants.forEach((p) => {
                    const id = Number(p.user_id);
                    if (!id) return;
                    const name = `${p.first_name || ''} ${p.last_name || ''}`.trim() || 'User';
                    next[id] = { name, image: p.image || '' };
                });
                window.conversationParticipantsById = next;
                window.isCollaborativeChat = Object.keys(next).length > 1;
                setMicButtonVisible(!!window.isCollaborativeChat);
                if (!window.isCollaborativeChat) {
                    disableCollabVoice();
                } else {
                    // Auto-join in LISTEN mode so audio works immediately.
                    // No mic permission prompt in listen mode.
                    enableCollabVoiceListen(cid);
                }
                refreshCollaboratorLabels();
            }
        } catch (e) {
            // best-effort only
        } finally {
            participantsFetchInFlight = null;
        }
    })();

    return participantsFetchInFlight;
}

function getCollaboratorNameById(userId) {
    const id = Number(userId);
    if (!id) return '';
    return window.conversationParticipantsById?.[id]?.name || `User ${id}`;
}

function refreshCollaboratorLabels() {
    document.querySelectorAll('.message.collab-message[data-sender-user-id]').forEach((el) => {
        const senderId = Number(el.dataset.senderUserId);
        if (!senderId) return;
        const label = el.querySelector('.collab-name');
        if (!label) return;
        const name = getCollaboratorNameById(senderId);
        const isBot = el.classList.contains('bot-message');
        label.textContent = isBot ? `Apilageai replies for ${name}` : name;
    });
}

// === Smooth Streaming State ===

// --- Smooth Streaming State ---
const streamingState = {
    buffer: '',           // Full content received from backend
    displayedLength: 0,   // Characters already displayed
    animationFrame: null, // RAF ID for smooth animation
    lastRenderTime: 0,    // Timestamp of last render
    charsPerFrame: 3,     // Characters to render per frame (adjustable for speed)
    minFrameTime: 16,     // Minimum ms between frames (~60fps)
    isAnimating: false,
    messageId: null,
    lastCheckedLineCount: 0,
    lastCheckedIndex: 0
};


// --- DOM References ---
// === Global DOM References (declared early to avoid ReferenceError) ===
const fileInput = document.getElementById("fileInput");
const previewWrapper = document.querySelector(".preview-wrapper");
const documentInput = document.getElementById("documentInput");
const documentPreviewWrapper = document.getElementById("document-preview-wrapper");
const documentAttachmentContainer = document.getElementById("document-attachment-container");
const documentReferenceContainer = document.getElementById("document-reference-container");
const documentReferenceToggle = document.getElementById("documentReferenceToggle");
const uploadDocumentBtn = document.getElementById("uploadDocumentBtn");
if (!Array.isArray(window.uploadedDocuments)) window.uploadedDocuments = [];
window.documentReferenceEnabled = !!window.documentReferenceEnabled;


// --- Mermaid Rendering ---
// Initialize Mermaid (lazy-loaded)
const MERMAID_CDN_URL = 'https://cdn.jsdelivr.net/npm/mermaid@10/dist/mermaid.min.js';
let mermaidReadyPromise = null;
const MATHJAX_CDN_URL = 'https://cdn.jsdelivr.net/npm/mathjax@3/es5/tex-svg.js';
let mathJaxReadyPromise = null;

function loadScriptOnce(url, id) {
    return new Promise((resolve, reject) => {
        const existing = id ? document.getElementById(id) : null;
        if (existing) {
            existing.addEventListener('load', () => resolve());
            existing.addEventListener('error', () => reject(new Error(`Failed to load ${url}`)));
            // If already loaded, resolve immediately.
            if ((existing.dataset && existing.dataset.loaded === '1') || existing.readyState === 'complete') {
                resolve();
            }
            return;
        }
        const script = document.createElement('script');
        if (id) script.id = id;
        script.src = url;
        script.async = true;
        script.onload = () => {
            if (script.dataset) script.dataset.loaded = '1';
            resolve();
        };
        script.onerror = () => reject(new Error(`Failed to load ${url}`));
        document.head.appendChild(script);
    });
}

function ensureMermaid() {
    if (typeof mermaid !== 'undefined' && typeof mermaid.initialize === 'function') {
        if (!window.__apilage_mermaid_inited) {
            mermaid.initialize({
                startOnLoad: false,
                theme: "default",
                flowchart: { htmlLabels: true, useMaxWidth: true },
                sequence: { useMaxWidth: true }
            });
            window.__apilage_mermaid_inited = true;
        }
        return Promise.resolve(mermaid);
    }
    if (mermaidReadyPromise) return mermaidReadyPromise;
    mermaidReadyPromise = loadScriptOnce(MERMAID_CDN_URL, 'mermaid-lib')
        .then(() => {
            if (typeof mermaid === 'undefined' || typeof mermaid.initialize !== 'function') {
                throw new Error('Mermaid failed to initialize');
            }
            if (!window.__apilage_mermaid_inited) {
                mermaid.initialize({
                    startOnLoad: false,
                    theme: "default",
                    flowchart: { htmlLabels: true, useMaxWidth: true },
                    sequence: { useMaxWidth: true }
                });
                window.__apilage_mermaid_inited = true;
            }
            return mermaid;
        })
        .catch((err) => {
            mermaidReadyPromise = null;
            throw err;
        });
    return mermaidReadyPromise;
}

function ensureMathJax() {
    if (window.MathJax?.typesetPromise) return Promise.resolve(window.MathJax);
    if (mathJaxReadyPromise) return mathJaxReadyPromise;
    mathJaxReadyPromise = loadScriptOnce(MATHJAX_CDN_URL, 'mathjax-lib')
        .then(() => {
            if (window.MathJax?.startup?.promise) {
                return window.MathJax.startup.promise;
            }
            return null;
        })
        .then(() => {
            if (!window.MathJax?.typesetPromise) {
                throw new Error('MathJax failed to initialize');
            }
            return window.MathJax;
        })
        .catch((err) => {
            mathJaxReadyPromise = null;
            throw err;
        });
    return mathJaxReadyPromise;
}

// Throttled MathJax renderer to allow incremental rendering during streaming

// --- MathJax Rendering ---
const mathJaxRenderState = {
    timer: null,
    inFlight: false,
    pending: false,
    lastTypesetAt: 0,
    minInterval: 60,
    lastElement: null
};

function runMathJaxTypeset(element) {
    if (!window.MathJax?.typesetPromise) return;
    if (!element || !element.isConnected) return;
    mathJaxRenderState.inFlight = true;
    MathJax.typesetPromise([element])
        .catch(err => console.error('MathJax error:', err))
        .finally(() => {
            mathJaxRenderState.inFlight = false;
            mathJaxRenderState.lastTypesetAt = Date.now();
            if (mathJaxRenderState.pending) {
                mathJaxRenderState.pending = false;
                queueMathJaxTypeset(mathJaxRenderState.lastElement || element);
            }
        });
}

function queueMathJaxTypeset(element, options = {}) {
    if (!element || !element.isConnected) return;
    if (!window.MathJax?.typesetPromise) {
        ensureMathJax()
            .then(() => {
                if (element && element.isConnected) queueMathJaxTypeset(element, options);
            })
            .catch(() => { });
        return;
    }

    const { force = false } = options;
    mathJaxRenderState.lastElement = element;

    if (mathJaxRenderState.inFlight) {
        mathJaxRenderState.pending = true;
        return;
    }

    const now = Date.now();
    const elapsed = now - mathJaxRenderState.lastTypesetAt;

    if (force || elapsed >= mathJaxRenderState.minInterval) {
        if (mathJaxRenderState.timer) {
            clearTimeout(mathJaxRenderState.timer);
            mathJaxRenderState.timer = null;
        }
        runMathJaxTypeset(element);
        return;
    }

    if (mathJaxRenderState.timer) return;
    const delay = Math.max(25, mathJaxRenderState.minInterval - elapsed);
    mathJaxRenderState.timer = setTimeout(() => {
        mathJaxRenderState.timer = null;
        if (mathJaxRenderState.inFlight) {
            mathJaxRenderState.pending = true;
            return;
        }
        runMathJaxTypeset(mathJaxRenderState.lastElement || element);
    }, delay);
}


// --- Mermaid Normalization + Export ---
function normalizeMermaidCode(rawCode) {
    let code = String(rawCode || "").replace(/\r\n/g, "\n").trim();
    if (!code) return "";

    const collapseLabelNewlines = (input) => {
        let out = "";
        const stack = [];
        let inQuote = false;
        let quoteChar = "";
        for (let i = 0; i < input.length; i++) {
            const ch = input[i];
            const prev = i > 0 ? input[i - 1] : "";
            if (inQuote) {
                if (ch === "\n" && stack.length) {
                    out += "\\n";
                    continue;
                }
                if (ch === quoteChar && prev !== "\\") {
                    inQuote = false;
                }
                out += ch;
                continue;
            }
            if (ch === '"' || ch === "'") {
                inQuote = true;
                quoteChar = ch;
                out += ch;
                continue;
            }
            if (ch === "[" || ch === "(" || ch === "{") {
                stack.push(ch);
                out += ch;
                continue;
            }
            if (ch === "]" || ch === ")" || ch === "}") {
                if (stack.length) stack.pop();
                out += ch;
                continue;
            }
            if (ch === "\n" && stack.length) {
                out += "\\n";
                continue;
            }
            out += ch;
        }
        return out;
    };

    code = collapseLabelNewlines(code);

    const directiveRegex = /^(graph|flowchart|sequenceDiagram|classDiagram|stateDiagram|stateDiagram-v2|erDiagram|journey|gantt|pie|gitGraph|mindmap|timeline|sankey|quadrantChart|C4Context|C4Container|C4Component|C4Dynamic|requirementDiagram|block-beta)\b/;
    const firstLine = code.split("\n").find((line) => {
        const trimmed = line.trim();
        return trimmed && !trimmed.startsWith("%%");
    });

    const normalizeLabel = (label) => {
        if (!/<br\s*\/?>/i.test(label) && !/\\n/.test(label)) return null;
        const hasQuotes = /^\s*".*"\s*$/.test(label);
        const updated = label.replace(/<br\s*\/?>/gi, "\\n");
        if (hasQuotes) return updated.trim();
        const safe = updated.replace(/"/g, "'");
        return `"${safe}"`;
    };

    code = code.replace(/\[([^\]\n]*?)\]/g, (match, label) => {
        const normalized = normalizeLabel(label);
        if (!normalized) return match;
        return `[${normalized}]`;
    });

    code = code.replace(/\(([^\)\n]*?)\)/g, (match, label) => {
        const normalized = normalizeLabel(label);
        if (!normalized) return match;
        return `(${normalized})`;
    });

    code = code.replace(/<br\s*\/?>/gi, "\\n");

    if (firstLine && !directiveRegex.test(firstLine.trim())) {
        if (/-->|---|<--|<->|==/.test(code)) {
            code = `flowchart TD\n${code}`;
        }
    }

    return code;
}

function getMermaidExportData(wrapper) {
    const svgEl = wrapper?.querySelector("svg");
    if (!svgEl) return null;

    let svgData = new XMLSerializer().serializeToString(svgEl);
    if (!svgData.match(/<svg[^>]+xmlns=/)) {
        svgData = svgData.replace("<svg", '<svg xmlns="http://www.w3.org/2000/svg"');
    }

    const rect = svgEl.getBoundingClientRect();
    const width = Math.max(1, Math.ceil(rect.width || svgEl.viewBox?.baseVal?.width || 800));
    const height = Math.max(1, Math.ceil(rect.height || svgEl.viewBox?.baseVal?.height || 600));

    return { svgData, width, height };
}

function downloadMermaidSvg(wrapper, baseName) {
    const data = getMermaidExportData(wrapper);
    if (!data) return;

    const blob = new Blob([data.svgData], { type: "image/svg+xml;charset=utf-8" });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = url;
    link.download = `${baseName}.svg`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    setTimeout(() => URL.revokeObjectURL(url), 250);
}

function downloadMermaidPng(wrapper, baseName) {
    if (window.html2canvas) {
        window.html2canvas(wrapper, {
            backgroundColor: null,
            scale: 2,
            ignoreElements: (el) => el?.classList?.contains("mermaid-actions")
        }).then((canvas) => {
            const link = document.createElement("a");
            link.href = canvas.toDataURL("image/png");
            link.download = `${baseName}.png`;
            document.body.appendChild(link);
            link.click();
            document.body.removeChild(link);
        });
        return;
    }

    const data = getMermaidExportData(wrapper);
    if (!data) return;

    const { svgData, width, height } = data;
    const svgBlob = new Blob([svgData], { type: "image/svg+xml;charset=utf-8" });
    const url = URL.createObjectURL(svgBlob);
    const img = new Image();
    img.onload = () => {
        const scale = window.devicePixelRatio || 1;
        const canvas = document.createElement("canvas");
        canvas.width = Math.max(1, Math.floor(width * scale));
        canvas.height = Math.max(1, Math.floor(height * scale));
        const ctx = canvas.getContext("2d");
        ctx.scale(scale, scale);
        ctx.drawImage(img, 0, 0, width, height);

        const link = document.createElement("a");
        link.href = canvas.toDataURL("image/png");
        link.download = `${baseName}.png`;
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
        URL.revokeObjectURL(url);
    };
    img.onerror = () => {
        URL.revokeObjectURL(url);
    };
    img.src = url;
}

async function renderMermaidBlocks(element) {
    if (!element) return;
    if (typeof mermaid === "undefined" || typeof mermaid.render !== "function") {
        const retries = Number(element.dataset?.mermaidRetry || 0);
        if (retries < 3) {
            element.dataset.mermaidRetry = String(retries + 1);
            try {
                await ensureMermaid();
            } catch (_) {
                // fall through to retry
            }
            setTimeout(() => renderMermaidBlocks(element), 400);
        }
        return;
    }

    const blocks = element.querySelectorAll("code.language-mermaid, pre.mermaid, .mermaid-block");
    if (!blocks.length) return;

    blocks.forEach((block) => {
        if (block.dataset?.mermaidProcessed === "true") return;
        block.dataset.mermaidProcessed = "true";
        const rawCode = block.textContent.trim();
        if (!rawCode) return;

        const wrapper = document.createElement("div");
        wrapper.className = "mermaid-box";
        wrapper.dataset.mermaidName = `mermaid-diagram-${Date.now()}`;

        const header = document.createElement("div");
        header.className = "mermaid-box-header";
        header.innerHTML = `
            <span class="mermaid-title">Mermaid diagram</span>
            <div class="mermaid-actions">
                <button type="button" class="mermaid-action-btn" data-format="svg" disabled>SVG</button>
                <button type="button" class="mermaid-action-btn" data-format="png" disabled>PNG</button>
            </div>
        `;

        const body = document.createElement("div");
        body.className = "mermaid-box-body";
        const container = document.createElement("div");
        container.className = "mermaid";
        body.appendChild(container);
        wrapper.appendChild(header);
        wrapper.appendChild(body);
        block.replaceWith(wrapper);

        const enableActions = () => {
            wrapper.querySelectorAll(".mermaid-action-btn").forEach((btn) => {
                btn.disabled = false;
            });
        };

        const handleDownload = (e) => {
            const btn = e.target.closest(".mermaid-action-btn");
            if (!btn || btn.disabled) return;
            const baseName = wrapper.dataset.mermaidName || `mermaid-diagram-${Date.now()}`;
            if (btn.dataset.format === "svg") downloadMermaidSvg(wrapper, baseName);
            if (btn.dataset.format === "png") downloadMermaidPng(wrapper, baseName);
        };

        wrapper.addEventListener("click", handleDownload);

        const attemptRender = async (code) => {
            const renderId = `mermaid-${Date.now()}-${Math.floor(Math.random() * 100000)}`;
            const { svg, bindFunctions } = await mermaid.render(renderId, code);
            container.innerHTML = svg;
            if (typeof bindFunctions === "function") {
                bindFunctions(container);
            }
            enableActions();
        };

        const normalized = normalizeMermaidCode(rawCode);
        attemptRender(normalized)
            .catch((err) => {
                if (normalized !== rawCode) {
                    attemptRender(rawCode).catch(() => {
                        console.error("Mermaid render error:", err);
                        container.innerHTML = `<pre class="mermaid-error">Diagram render failed.</pre>`;
                    });
                    return;
                }
                console.error("Mermaid render error:", err);
                container.innerHTML = `<pre class="mermaid-error">Diagram render failed.</pre>`;
            });
    });
}


// --- Excalidraw Support ---
let excalidrawUtilsPromise = null;

function loadExcalidrawUtils() {
    if (excalidrawUtilsPromise) return excalidrawUtilsPromise;
    excalidrawUtilsPromise = import("https://cdn.jsdelivr.net/npm/@excalidraw/utils@latest/+esm")
        .then((mod) => {
            const api = mod?.default || mod;
            if (!api || typeof api.exportToSvg !== "function" || typeof api.exportToBlob !== "function") {
                throw new Error("Excalidraw utils export functions not available.");
            }
            return api;
        })
        .catch((err) => {
            console.error("Failed to load Excalidraw utils:", err);
            excalidrawUtilsPromise = null;
            throw err;
        });
    return excalidrawUtilsPromise;
}

function looksLikeExcalidrawText(raw) {
    if (!raw) return false;
    const text = String(raw).toLowerCase();
    if (text.includes('"excalidraw"') || text.includes('excalidraw.com')) return true;
    if (text.includes('"elements"') && (text.includes('"strokecolor"') || text.includes('"roughness"') || text.includes('"fillstyle"') || text.includes('"roundness"'))) {
        return true;
    }
    return false;
}

function isLikelyExcalidrawRoot(parsed) {
    if (!parsed) return false;
    if (parsed.type === "excalidraw") return true;
    if (typeof parsed.source === "string" && parsed.source.toLowerCase().includes("excalidraw")) return true;
    const elements = parsed.elements || parsed?.scene?.elements;
    if (!Array.isArray(elements) || !elements.length) return false;
    const sample = elements.find((el) => el && typeof el === "object");
    if (!sample) return false;
    const hasCore =
        typeof sample.type === "string" &&
        typeof sample.x === "number" &&
        typeof sample.y === "number";
    const hasStyle =
        "strokeColor" in sample ||
        "roughness" in sample ||
        "fillStyle" in sample ||
        "roundness" in sample;
    return hasCore && hasStyle;
}

function parseExcalidrawScene(raw) {
    if (!raw || !looksLikeExcalidrawText(raw)) return null;
    let parsed;
    try {
        parsed = JSON.parse(raw);
    } catch (_) {
        return null;
    }
    if (!parsed) return null;

    if (Array.isArray(parsed)) {
        const wrapped = { elements: parsed, appState: {}, files: {} };
        return isLikelyExcalidrawRoot(wrapped) ? wrapped : null;
    }

    if (!isLikelyExcalidrawRoot(parsed)) return null;

    if (parsed.scene && parsed.scene.elements) {
        return {
            elements: parsed.scene.elements,
            appState: parsed.scene.appState || {},
            files: parsed.scene.files || {},
            title: parsed.title || parsed.scene.title || ""
        };
    }

    if (parsed.elements) {
        return {
            elements: parsed.elements,
            appState: parsed.appState || {},
            files: parsed.files || {},
            title: parsed.title || ""
        };
    }

    return null;
}

function buildExcalidrawAppState(scene) {
    const isDark = document.body?.dataset?.theme === "dark";
    const base = {
        exportBackground: true,
        exportWithDarkMode: isDark,
        viewBackgroundColor: isDark ? "#0f172a" : "#ffffff"
    };
    return Object.assign({}, base, scene?.appState || {});
}

function downloadExcalidrawSvg(wrapper, baseName) {
    const svgEl = wrapper?.querySelector("svg");
    if (!svgEl) return;
    let svgData = new XMLSerializer().serializeToString(svgEl);
    if (!svgData.match(/<svg[^>]+xmlns=/)) {
        svgData = svgData.replace("<svg", '<svg xmlns="http://www.w3.org/2000/svg"');
    }
    const blob = new Blob([svgData], { type: "image/svg+xml;charset=utf-8" });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = url;
    link.download = `${baseName}.svg`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    setTimeout(() => URL.revokeObjectURL(url), 250);
}

async function downloadExcalidrawPng(scene, baseName) {
    try {
        const utils = await loadExcalidrawUtils();
        const blob = await utils.exportToBlob({
            elements: scene.elements,
            appState: buildExcalidrawAppState(scene),
            files: scene.files || {},
            mimeType: "image/png"
        });
        if (!blob) return;
        const url = URL.createObjectURL(blob);
        const link = document.createElement("a");
        link.href = url;
        link.download = `${baseName}.png`;
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
        setTimeout(() => URL.revokeObjectURL(url), 250);
    } catch (err) {
        console.error("Excalidraw PNG export failed:", err);
    }
}

async function renderExcalidrawBlocks(element) {
    if (!element) return;
    const blocks = element.querySelectorAll("code.language-excalidraw, pre.excalidraw, .excalidraw-block, pre code, code.language-json");
    if (!blocks.length) return;

    let utils;
    try {
        utils = await loadExcalidrawUtils();
    } catch (_) {
        return;
    }

    for (const block of blocks) {
        const target = block.tagName?.toLowerCase() === "code" && block.parentElement?.tagName?.toLowerCase() === "pre"
            ? block.parentElement
            : block;
        if (target.dataset?.excalidrawProcessed === "true") continue;
        target.dataset.excalidrawProcessed = "true";
        const raw = block.textContent.trim();
        if (!raw) continue;

        let scene = parseExcalidrawScene(raw);
        if (!scene) continue;
        const wrapper = document.createElement("div");
        wrapper.className = "excalidraw-box";
        wrapper.dataset.excalidrawName = `excalidraw-sketch-${Date.now()}`;

        const header = document.createElement("div");
        header.className = "excalidraw-box-header";
        const headerTitle = scene?.title ? escapeHtml(String(scene.title)) : "Excalidraw sketch";
        header.innerHTML = `
            <span class="excalidraw-title">${headerTitle}</span>
            <div class="excalidraw-actions">
                <button type="button" class="excalidraw-action-btn" data-action="zoom_reset" title="Reset view"><i class="fa-solid fa-arrows-rotate"></i> Reset</button>
                <button type="button" class="excalidraw-action-btn" data-action="save_png" title="Save as PNG"><i class="fa-solid fa-image"></i> PNG</button>
                <button type="button" class="excalidraw-action-btn excalidraw-fullscreen-btn" data-action="fullscreen" title="Edit in sidebar"><i class="fa-solid fa-expand"></i> Full Screen</button>
            </div>
        `;

        const body = document.createElement("div");
        body.className = "excalidraw-box-body";
        const loadingEl = document.createElement("div");
        loadingEl.className = "excalidraw-loading";
        loadingEl.innerHTML = `<span class="excalidraw-spinner" aria-hidden="true"></span>Rendering sketch…`;

        const viewport = document.createElement("div");
        viewport.className = "excalidraw-viewport";
        viewport.style.display = "none";
        body.appendChild(loadingEl);
        body.appendChild(viewport);
        wrapper.appendChild(header);
        wrapper.appendChild(body);
        target.replaceWith(wrapper);

        if (!scene || !Array.isArray(scene.elements) || !scene.elements.length) {
            body.innerHTML = `<pre class="excalidraw-error">Invalid Excalidraw scene.</pre>`;
            continue;
        }

        let currentSvg = null;
        const zoomState = { scale: 1, x: 0, y: 0 };
        const zoomLimits = { min: 0.35, max: 4 };

        const applyTransform = () => {
            if (!currentSvg) return;
            currentSvg.style.transformOrigin = "0 0";
            currentSvg.style.transform = `translate(${zoomState.x}px, ${zoomState.y}px) scale(${zoomState.scale})`;
            currentSvg.style.willChange = "transform";
        };

        const fitToView = () => {
            if (!currentSvg) return;
            const rect = viewport.getBoundingClientRect();
            if (!rect.width || !rect.height) return;
            const vb = currentSvg.viewBox?.baseVal;
            const viewW = vb?.width || currentSvg.getBoundingClientRect().width || 0;
            const viewH = vb?.height || currentSvg.getBoundingClientRect().height || 0;
            if (!viewW || !viewH) return;
            const scale = Math.min(rect.width / viewW, rect.height / viewH, 1);
            zoomState.scale = Math.max(zoomLimits.min, Math.min(zoomLimits.max, scale));
            zoomState.x = (rect.width - viewW * zoomState.scale) / 2;
            zoomState.y = (rect.height - viewH * zoomState.scale) / 2;
            applyTransform();
        };

        const zoomBy = (factor, center = null) => {
            if (!currentSvg) return;
            const rect = viewport.getBoundingClientRect();
            const cx = center?.x ?? rect.width / 2;
            const cy = center?.y ?? rect.height / 2;
            const nextScale = Math.max(zoomLimits.min, Math.min(zoomLimits.max, zoomState.scale * factor));
            const scaleRatio = nextScale / zoomState.scale;
            zoomState.x = cx - (cx - zoomState.x) * scaleRatio;
            zoomState.y = cy - (cy - zoomState.y) * scaleRatio;
            zoomState.scale = nextScale;
            applyTransform();
        };

        const enableActions = () => {
            wrapper.querySelectorAll(".excalidraw-action-btn[data-format]").forEach((btn) => {
                btn.disabled = false;
            });
        };

        let editorEl = null;
        let lastRaw = raw;

        const closeEditor = () => {
            if (editorEl && editorEl.parentNode) {
                editorEl.parentNode.removeChild(editorEl);
            }
            editorEl = null;
        };

        const openEditor = () => {
            if (editorEl) {
                closeEditor();
                return;
            }
            editorEl = document.createElement("div");
            editorEl.className = "excalidraw-json-editor";
            editorEl.innerHTML = `
                <textarea class="excalidraw-json-textarea" spellcheck="false"></textarea>
                <div class="excalidraw-json-actions">
                    <button type="button" class="excalidraw-action-btn" data-action="apply_edit">Apply</button>
                    <button type="button" class="excalidraw-action-btn" data-action="cancel_edit">Cancel</button>
                </div>
                <div class="excalidraw-json-error" role="alert"></div>
            `;
            const textarea = editorEl.querySelector(".excalidraw-json-textarea");
            if (textarea) textarea.value = lastRaw;
            wrapper.appendChild(editorEl);
        };

        const renderScene = async (nextScene) => {
            loadingEl.style.display = "";
            viewport.style.display = "none";
            try {
                const svg = await utils.exportToSvg({
                    elements: nextScene.elements,
                    appState: buildExcalidrawAppState(nextScene),
                    files: nextScene.files || {},
                    exportPadding: Number(nextScene.exportPadding || 16),
                    exportScale: Number(nextScene.exportScale || 1)
                });
                currentSvg = svg;
                svg.style.width = "100%";
                svg.style.height = "auto";
                svg.style.display = "block";
                svg.setAttribute("draggable", "false");
                viewport.innerHTML = "";
                viewport.appendChild(svg);
                loadingEl.style.display = "none";
                viewport.style.display = "";
                enableActions();
                requestAnimationFrame(() => fitToView());
            } catch (err) {
                console.error("Excalidraw render failed:", err);
                currentSvg = null;
                loadingEl.style.display = "none";
                viewport.style.display = "";
                viewport.innerHTML = `<pre class="excalidraw-error">Sketch render failed.</pre>`;
            }
        };

        const handleAction = (e) => {
            const btn = e.target.closest(".excalidraw-action-btn");
            if (!btn || btn.disabled) return;
            const action = btn.dataset.action;
            if (action === "zoom_reset") {
                fitToView();
                return;
            }
            if (action === "save_png") {
                const baseName = wrapper.dataset.excalidrawName || `excalidraw-sketch-${Date.now()}`;
                downloadExcalidrawPng(scene, baseName);
                return;
            }
            if (action === "fullscreen") {
                // Open the right sidebar with the scene loaded into the Excalidraw editor
                const rawScene = {
                    elements: Array.isArray(scene?.elements) ? scene.elements : [],
                    appState: (scene?.appState && typeof scene.appState === 'object') ? scene.appState : {},
                    files: (scene?.files && typeof scene.files === 'object') ? scene.files : {},
                };
                const editableAppState = Object.assign({}, rawScene.appState || {}, {
                    viewModeEnabled: false,
                    zenModeEnabled: false,
                });
                const editorScene = {
                    elements: rawScene.elements || [],
                    appState: editableAppState,
                    files: rawScene.files || {},
                };
                const normalizedScene = (typeof normalizeExcalidrawScene === 'function')
                    ? normalizeExcalidrawScene(editorScene)
                    : editorScene;
                excalidrawBlockRemoteUntil = Date.now() + 2000;
                excalidrawIgnoreEmptyRemoteUntil = Date.now() + 8000;
                try {
                    excalidrawSkipClearOnce = true;
                    const preload = (typeof normalizeExcalidrawScene === 'function')
                        ? normalizeExcalidrawScene(normalizedScene)
                        : {
                            elements: normalizedScene.elements || [],
                            appState: editableAppState || {},
                            files: normalizedScene.files || {},
                        };
                    preload.appState = Object.assign({}, preload.appState || {}, editableAppState);
                    excalidrawScene = preload;
                    excalidrawSceneHash = getSceneHash(preload);
                    excalidrawPendingScene = preload;
                } catch (_) { }

                // 1. Open the canvas sidebar first (this triggers Excalidraw mounting)
                if (typeof openCanvas === 'function') {
                    const sidebar = document.getElementById('sidebar');
                    if (sidebar && !sidebar.classList.contains('hidden')) {
                        sidebar.classList.add('hidden');
                        sidebar.setAttribute('aria-hidden', 'true');
                        try { sidebar.inert = true; } catch (_) { }
                        const toggleSidebarBtn = document.getElementById('toggleSidebar');
                        if (toggleSidebarBtn) toggleSidebarBtn.style.display = 'block';
                    }
                    openCanvas({ fullscreen: true });
                }
                excalidrawSkipClearOnce = false;
                // 2. Activate the canvas feature badge
                if (typeof window.setActiveFeature === 'function') {
                    window.setActiveFeature('canvas', { suppressCanvasOpen: true, keepActive: true });
                }

                // 3. Wait for Excalidraw to be fully mounted, THEN push scene data
                const pushSceneAfterMount = async () => {
                    try {
                        if (typeof ensureExcalidrawSidebarMounted === 'function') {
                            await ensureExcalidrawSidebarMounted();
                        }
                        // Small extra delay for React render to complete
                        await new Promise(r => setTimeout(r, 300));

                        // Push the scene data into the sidebar Excalidraw
                        if (typeof applyExcalidrawScene === 'function') {
                            applyExcalidrawScene(normalizedScene, { remote: true });
                        } else if (typeof excalidrawApi !== 'undefined' && excalidrawApi && typeof excalidrawApi.updateScene === 'function') {
                            excalidrawApi.updateScene({
                                elements: editorScene.elements,
                                appState: editableAppState,
                                files: editorScene.files || {},
                            });
                        }
                        if (editorScene.files && typeof excalidrawApi !== 'undefined' && excalidrawApi && typeof excalidrawApi.addFiles === 'function') {
                            excalidrawApi.addFiles(Object.values(editorScene.files));
                        }
                        try {
                            excalidrawScene = normalizeExcalidrawScene(normalizedScene);
                            excalidrawSceneHash = getSceneHash(excalidrawScene);
                            excalidrawPendingScene = excalidrawScene;
                            flushPendingExcalidrawScene();
                        } catch (_) { }

                        // Scroll to content for best view
                        await new Promise(r => setTimeout(r, 200));
                        if (typeof excalidrawApi !== 'undefined' && excalidrawApi && typeof excalidrawApi.scrollToContent === 'function') {
                            excalidrawApi.scrollToContent(editorScene.elements, {
                                fitToViewport: true,
                                animate: true,
                                duration: 300,
                            });
                        }
                    } catch (err) {
                        console.error('Failed to load scene into Excalidraw sidebar:', err);
                    }
                };
                pushSceneAfterMount();
                return;
            }
            if (action === "cancel_edit") {
                closeEditor();
                return;
            }
            if (action === "apply_edit") {
                const textarea = editorEl?.querySelector(".excalidraw-json-textarea");
                const errEl = editorEl?.querySelector(".excalidraw-json-error");
                const nextRaw = textarea ? textarea.value.trim() : "";
                const nextScene = parseExcalidrawScene(nextRaw);
                if (!nextScene) {
                    if (errEl) errEl.textContent = "Invalid Excalidraw JSON.";
                    return;
                }
                if (errEl) errEl.textContent = "";
                lastRaw = nextRaw;
                scene = nextScene;
                closeEditor();
                renderScene(scene);
                return;
            }
        };

        wrapper.addEventListener("click", handleAction);

        let isPanning = false;
        let panStart = { x: 0, y: 0 };
        let panOrigin = { x: 0, y: 0 };

        viewport.addEventListener("pointerdown", (e) => {
            if (e.button !== 0 && e.pointerType === "mouse") return;
            isPanning = true;
            viewport.classList.add("is-panning");
            panStart = { x: e.clientX, y: e.clientY };
            panOrigin = { x: zoomState.x, y: zoomState.y };
            try { viewport.setPointerCapture(e.pointerId); } catch (_) { }
        });

        viewport.addEventListener("pointermove", (e) => {
            if (!isPanning) return;
            const dx = e.clientX - panStart.x;
            const dy = e.clientY - panStart.y;
            zoomState.x = panOrigin.x + dx;
            zoomState.y = panOrigin.y + dy;
            applyTransform();
        });

        const endPan = (e) => {
            if (!isPanning) return;
            isPanning = false;
            viewport.classList.remove("is-panning");
            try { viewport.releasePointerCapture(e.pointerId); } catch (_) { }
        };

        viewport.addEventListener("pointerup", endPan);
        viewport.addEventListener("pointercancel", endPan);
        viewport.addEventListener("pointerleave", endPan);

        viewport.addEventListener("wheel", (e) => {
            if (!currentSvg) return;
            e.preventDefault();
            const rect = viewport.getBoundingClientRect();
            const cx = e.clientX - rect.left;
            const cy = e.clientY - rect.top;
            const factor = e.deltaY > 0 ? 0.9 : 1.1;
            zoomBy(factor, { x: cx, y: cy });
        }, { passive: false });

        renderScene(scene);
    }
}

// Normalize common shorthand like {a}n{b} into TeX-friendly ^{a}n_{b}

// --- LaTeX Helpers ---
function normalizeCombinationShorthand(mathText) {
    return mathText.replace(/\{([^}]+)\}\s*n\s*\{([^}]+)\}/g, (_, sup, sub) => `{}^{${sup.trim()}}n_{${sub.trim()}}`);
}

// Detect math delimiters on a per-line basis for streaming updates
function lineHasLatex(line) {
    if (!line) return false;
    return /(\$\$[^$]*\$\$|\$[^$]*\$|\\\([^)]*\\\)|\\\[[^\]]*\\\])/m.test(line);
}

function shouldForceTypesetForChunk(chunk) {
    if (!chunk) return false;
    return /(\n|\$\$|\$|\\\)|\\\]|\\\(|\\\[)/.test(chunk);
}

// Utility: Remove all thinking status indicators

// --- Thinking Status UI ---
function clearThinkingTexts(options = {}) {
    const keepLocal = !!options.keepLocal;
    document.querySelectorAll('.thinking-status').forEach(el => {
        if (keepLocal && el.classList.contains('thinking-status--local')) return;
        el.remove();
    });
}

function showThinkingStatus(text = 'Thinking..') {
    clearThinkingTexts();
    const statusEl = document.createElement('div');
    statusEl.className = 'thinking-status thinking-status--local';
    statusEl.setAttribute('aria-live', 'polite');
    statusEl.innerHTML = `
        <span class="status-icon" aria-hidden="true">•</span>
        <span class="status-text">${text}</span>
    `;

    const messagesContainer = document.getElementById('messages-container');
    if (messagesContainer) {
        messagesContainer.appendChild(statusEl);
        scrollToBottom();
        return statusEl;
    }

    const startContainer = document.querySelector('.chat-start-container');
    if (startContainer) {
        startContainer.appendChild(statusEl);
        return statusEl;
    }

    const chatAreaWrapper = document.querySelector('.chat-area-wrapper');
    const chatWrapper = document.querySelector('.chat-wrapper');
    if (chatAreaWrapper && chatWrapper) {
        chatAreaWrapper.insertBefore(statusEl, chatWrapper);
        return statusEl;
    }

    return statusEl;
}


// --- Attachment + Document Normalization ---
function normalizeAttachmentList(input) {
    if (!input) return [];
    if (Array.isArray(input)) {
        return input
            .map((item) => {
                if (!item) return "";
                if (typeof item === "object") return item.name || item.filename || "";
                return String(item);
            })
            .map((item) => String(item).trim())
            .filter(Boolean);
    }
    if (typeof input === "object") {
        const name = input.name || input.filename;
        return name ? [String(name).trim()] : [];
    }
    const str = String(input).trim();
    if (!str) return [];
    if (str.startsWith("[")) {
        try {
            const parsed = JSON.parse(str);
            if (Array.isArray(parsed)) {
                return parsed
                    .map((item) => {
                        if (!item) return "";
                        if (typeof item === "object") return item.name || item.filename || "";
                        return String(item);
                    })
                    .map((item) => String(item).trim())
                    .filter(Boolean);
            }
        } catch (_) { }
    }
    if (str.includes(",")) {
        return str
            .split(",")
            .map((item) => String(item).trim())
            .filter(Boolean);
    }
    return [str];
}

function normalizeDocumentList(input) {
    if (!input) return [];
    const normalizeItem = (item) => {
        if (!item) return null;
        if (typeof item === "object") {
            const id = String(item.id || item.document_id || item.doc_id || "").trim();
            if (!id) return null;
            const name = String(item.name || item.originalName || item.filename || "").trim();
            const filename = String(item.filename || item.stored_filename || item.file || "").trim();
            const mimeType = String(item.mimeType || item.mime_type || "").trim();
            return { id, name, filename, mimeType };
        }
        const id = String(item).trim();
        return id ? { id, name: "", filename: "", mimeType: "" } : null;
    };
    if (Array.isArray(input)) {
        return input.map(normalizeItem).filter(Boolean);
    }
    if (typeof input === "object") {
        const single = normalizeItem(input);
        return single ? [single] : [];
    }
    const str = String(input).trim();
    if (!str) return [];
    if (str.startsWith("[")) {
        try {
            const parsed = JSON.parse(str);
            if (Array.isArray(parsed)) {
                return parsed.map(normalizeItem).filter(Boolean);
            }
        } catch (_) { }
    }
    if (str.includes(",")) {
        return str
            .split(",")
            .map((item) => normalizeItem(item))
            .filter(Boolean);
    }
    const single = normalizeItem(str);
    return single ? [single] : [];
}


